{"cards": [{"node_code": "N_4d64e2a68e6f8adf", "definition": "研究制造现场物理执行层面的自动化技术，包括数控系统、运动控制、工业机器人集成、柔性制造单元及CAM/CAD数据在设备端的落地应用。", "boundary": "聚焦于“硬”自动化与设备级控制，涵盖从底层插补算法、伺服驱动到上层机器人轨迹规划及柔性产线集成。边界在于关注物理设备的运动执行、实时控制及硬件集成，不涉及纯软件信息架构（归入制造执行与信息集成）或基于数据模型的虚拟映射（归入数字孪生）。", "includes": ["数控系统原理、插补算法、伺服驱动及运动控制", "工业机器人编程、自动生产线布局及制造单元集成", "柔性制造系统（FMS）架构、CAM/CAD数据在设备端的转换与执行"], "excludes": ["不涉及具体设备控制的纯管理信息系统或ERP流程设计", "纯虚拟仿真环境下的数字孪生建模，若无实时物理设备交互"], "sibling_distinctions": [{"other_code": "N_d1d6ef05dd67a5c8", "rule": "本节点关注设备级的实时控制与物理执行（如NC代码执行、机器人动作）；兄弟节点关注车间级的信息流转、工单管理及数据集成（如MES、数据模型）。"}, {"other_code": "N_c2bd05bd9d1c4dba", "rule": "本节点关注物理实体的自动化控制与硬件集成；兄弟节点关注物理实体在虚拟空间的映射、同步及基于模型的仿真优化。"}, {"other_code": "N_539c92bd917b096f", "rule": "本节点关注确定性的自动化执行与常规控制；兄弟节点关注基于AI/大数据的非确定性自主决策、自适应优化及智能调度。"}], "cross_boundary_rule": "若研究侧重设备硬件结构、伺服电机选型或机械传动，主挂载“制造装备”；若侧重控制算法在特定设备上的实现与集成，主挂载本节点；若侧重跨设备的数据交换标准，主挂载“制造执行与信息集成”。"}, {"node_code": "N_d1d6ef05dd67a5c8", "definition": "研究制造车间层的信息管理系统、数据流转机制及企业级系统集成，涵盖MES、工单管理、CAD/CAPP/CAM数据贯通及制造数据互操作标准。", "boundary": "聚焦于制造过程中的“信息流”与“数据流”管理，即如何通过软件系统连接设计、计划、执行与监控环节。涵盖MES功能模块、车间数据采集、主数据管理及跨系统接口标准。边界在于关注信息架构、数据模型及系统集成逻辑，不涉及底层设备实时控制（归入制造自动化与数控）或虚拟映射技术（归入数字孪生）。", "includes": ["制造执行系统（MES）架构、工单调度、车间数据采集与监控", "CAD、CAPP、CAM数据贯通、PLM与ERP集成及企业级信息架构", "制造数据模型、主数据管理、OPC UA等互操作标准及数据治理"], "excludes": ["不涉及制造场景的通用数据库理论或纯软件工程方法", "底层数控系统的实时运动控制算法或伺服驱动硬件设计"], "sibling_distinctions": [{"other_code": "N_4d64e2a68e6f8adf", "rule": "本节点关注车间级的信息管理与数据集成（如MES、数据模型）；兄弟节点关注设备级的实时控制与物理执行（如NC、机器人控制）。"}, {"other_code": "N_c2bd05bd9d1c4dba", "rule": "本节点关注历史数据、流程数据及系统间的数据交换标准；兄弟节点关注实时状态同步、高保真模型映射及基于孪生体的仿真决策。"}, {"other_code": "N_539c92bd917b096f", "rule": "本节点关注数据的结构化存储、流转与集成；兄弟节点关注利用数据进行智能分析、预测性维护及自主优化决策。"}], "cross_boundary_rule": "若研究侧重数据在物理设备间的实时传输与控制指令下发，主挂载“制造自动化与数控”；若侧重数据在管理系统间的标准化交换、存储与流程驱动，主挂载本节点；若侧重数据驱动的虚拟模型更新，主挂载“数字孪生与数字主线”。"}, {"node_code": "N_c2bd05bd9d1c4dba", "definition": "研究物理制造实体在虚拟空间的映射、同步及全生命周期数据贯通技术，涵盖设备/产线数字孪生、模型-数据-状态同步机制及数字主线架构。", "boundary": "聚焦于“虚实映射”与“全生命周期数据贯通”，即如何通过高保真模型实时反映物理状态，并利用虚拟空间进行仿真、预测与优化。涵盖设备级到工厂级的孪生体构建、多源数据融合及数字主线（Digital Thread）数据流管理。边界在于关注虚拟模型与物理实体的交互机制及数据连续性，不涉及纯物理设备控制（归入制造自动化）或纯信息管理系统（归入制造执行）。", "includes": ["设备、产线及工厂级数字孪生体构建、多物理场仿真及虚实交互", "模型、数据与物理状态的实时同步机制、多源数据融合技术", "数字主线（Digital Thread）架构、全生命周期数据贯通及基于孪生的预测性维护"], "excludes": ["不涉及物理实体映射的纯计算机图形学或通用仿真算法", "纯硬件传感器设计或独立于孪生架构的通用MES功能模块"], "sibling_distinctions": [{"other_code": "N_4d64e2a68e6f8adf", "rule": "本节点关注虚拟模型对物理实体的映射、仿真及状态同步；兄弟节点关注物理实体的直接自动化控制与硬件集成。"}, {"other_code": "N_d1d6ef05dd67a5c8", "rule": "本节点关注实时状态同步、高保真模型及全生命周期数据贯通（数字主线）；兄弟节点关注车间级信息管理系统（MES）及通用数据互操作标准。"}, {"other_code": "N_539c92bd917b096f", "rule": "本节点关注孪生体的构建、同步机制及基于模型的仿真优化；兄弟节点关注基于AI/大数据的自主决策算法、智能调度及非确定性优化策略。"}], "cross_boundary_rule": "若研究侧重孪生体中具体控制算法的验证或设备硬件改造，主挂载“制造自动化与数控”；若侧重孪生数据在MES中的存储与流程管理，主挂载“制造执行与信息集成”；若侧重孪生模型本身的构建、同步机制及虚实交互，主挂载本节点。"}]}
